type Visitor interface{ VisitDefault(Element) }
type UnionVisitor interface {
	Visitor
	VisitUnion(*UnionShape) // the extended protocol
}
func (u *UnionShape) Accept(v Visitor) {
	if uv, ok := v.(UnionVisitor); ok { // capability probe, no inheritance needed
		uv.VisitUnion(u)
		return
	}
	v.VisitDefault(u) // visitor written before UnionShape existed
}
